// Package events is the JSONL event stream `codex exec --json` prints.
package events

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

// Stream writes the events of one run, one JSON object per line.
type Stream struct {
	out  io.Writer
	next int
}

// New is a stream on out.
func New(out io.Writer) *Stream { return &Stream{out: out} }

func (s *Stream) emit(v map[string]any) {
	enc := json.NewEncoder(s.out)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(v)
}

func (s *Stream) newID() string {
	id := fmt.Sprintf("item_%d", s.next)
	s.next++
	return id
}

// ThreadStarted opens the run: the thread is the session.
func (s *Stream) ThreadStarted(id string) {
	s.emit(map[string]any{"type": "thread.started", "thread_id": id})
}

// TurnStarted opens a turn: from the user's prompt to the final message.
func (s *Stream) TurnStarted() { s.emit(map[string]any{"type": "turn.started"}) }

// TurnCompleted closes the turn. The mock calls no model, so it used no tokens.
func (s *Stream) TurnCompleted() {
	s.emit(map[string]any{"type": "turn.completed", "usage": map[string]int{
		"input_tokens": 0, "cached_input_tokens": 0, "cache_write_input_tokens": 0,
		"output_tokens": 0, "reasoning_output_tokens": 0}})
}

// AgentMessage reports a message from the agent.
func (s *Stream) AgentMessage(text string) {
	s.emit(map[string]any{"type": "item.completed", "item": map[string]any{
		"id": s.newID(), "type": "agent_message", "text": text}})
}

// ShellCommand is how Codex shows a command the shell ran.
func ShellCommand(command string) string {
	return "/bin/sh -c '" + strings.ReplaceAll(command, "'", `'\''`) + "'"
}

// CommandStarted reports a command that began; the id pairs it with its end.
func (s *Stream) CommandStarted(command string) string {
	id := s.newID()
	s.emit(map[string]any{"type": "item.started", "item": map[string]any{
		"id": id, "type": "command_execution", "command": ShellCommand(command),
		"aggregated_output": "", "exit_code": nil, "status": "in_progress"}})
	return id
}

// CommandCompleted reports how a started command ended: completed on exit 0,
// failed otherwise.
func (s *Stream) CommandCompleted(id, command, output string, exit int) {
	status := "completed"
	if exit != 0 {
		status = "failed"
	}
	s.emit(map[string]any{"type": "item.completed", "item": map[string]any{
		"id": id, "type": "command_execution", "command": ShellCommand(command),
		"aggregated_output": output, "exit_code": exit, "status": status}})
}
package tools

import (
	"fmt"
	"strings"
)

// Message is what the agent is told of a shell command that ran in the
// foreground: its output with the trailing newlines trimmed, and isError
// false; for a command that ended with a non-zero status, an error that
// states the exit code and then the output.
//
// sr:capability bash-tool-result
func (r BashResult) Message() (text string, isError bool) {
	out := strings.TrimRight(r.Output, "\n")
	if !r.Failed() {
		return out, false
	}
	msg := fmt.Sprintf("Exit code %d", r.ExitCode)
	if out != "" {
		msg += "\n" + out
	}
	return msg, true
}

// MessageFor is Message for a command some of whose exit status 1 is not a
// failure: when the last command of the pipeline is one of benign (a search or
// a comparison, for which 1 only says nothing matched or the inputs differ),
// the output is a valid result.
func (r BashResult) MessageFor(command string, benign []string) (text string, isError bool) {
	if r.ExitCode == 1 && lastCommandIn(command, benign) {
		return strings.TrimRight(r.Output, "\n"), false
	}
	return r.Message()
}

// lastCommandIn is whether the last command of a shell line (after its last
// "|", "&&", "||" or ";") runs one of names, ignoring leading VAR=value words;
// "git diff" and "git grep" are named as the two words.
func lastCommandIn(command string, names []string) bool {
	seg := command
	for _, sep := range []string{"|", "&&", ";"} {
		if i := strings.LastIndex(seg, sep); i >= 0 {
			seg = seg[i+len(sep):]
		}
	}
	words := strings.Fields(seg)
	for len(words) > 0 && strings.Contains(words[0], "=") && !strings.HasPrefix(words[0], "=") {
		words = words[1:]
	}
	if len(words) == 0 {
		return false
	}
	for _, n := range names {
		parts := strings.Fields(n)
		if len(words) >= len(parts) && strings.Join(words[:len(parts)], " ") == n {
			return true
		}
	}
	return false
}
