git checkout bd7e1e2 -- codex-mock/e2e/001_hooks/replay_test.go codex-mock/internal/runner/tool_host.go
python3 - <<'EOF'
p='codex-mock/internal/events/stream.go'
s=open(p).read()
s=s.replace("""// CommandCompleted reports how a started command ended: completed on exit 0,
// failed otherwise.
""","""// CommandCompleted reports how a started command ended: its exit status and
// everything it printed, and a status of completed on exit 0, failed otherwise
// (recorded: runs/shell-exit-status). The agent is told the output as it is,
// failed or not; the failure shows only here.
// sr:provides bash-tool-result/codex
""")
open(p,'w').write(s)
p='codex-mock/e2e/001_hooks/shell_result_test.go'
s=open(p).read()
s=s.replace('''	rec := loadRecording(t, "shell-exit-status")
	got := replay(t, rec)
''','''	rec := loadRecording(t, "shell-exit-status")
	// the commands the model asked for, as the recorded hooks saw them
	rec.calls = nil
	for _, p := range jsonLines(readFile(t, filepath.Join(rec.sample, "payloads.jsonl"))) {
		if in, ok := p["tool_input"].(map[string]any); ok && p["hook_event_name"] == "PostToolUse" {
			rec.calls = append(rec.calls, in["command"].(string))
		}
	}
	require.Len(t, rec.calls, 5)
	got := replay(t, rec)
''')
s=s.replace('''	byExit :=''','''	// PostToolUse fires after every one of them, failed or not, with the
	// output as the response: the same payloads the recording holds
	var wantPost, gotPost []map[string]any
	for _, l := range jsonLines(readFile(t, filepath.Join(rec.sample, "payloads.jsonl"))) {
		if l["hook_event_name"] == "PostToolUse" {
			wantPost = append(wantPost, l)
		}
	}
	for _, l := range got.hookLog() {
		if l["hook_event_name"] == "PostToolUse" {
			gotPost = append(gotPost, l)
		}
	}
	require.Len(t, wantPost, 5)
	assert.Equal(t, sortedHookLines(wantPost), sortedHookLines(gotPost))

	byExit :=''')
open(p,'w').write(s)
EOF
gofmt -l codex-mock; go test -count=1 ./codex-mock/... 2>&1 | tail -15

